G=load()
def collapse(seq):
    out=[seq[0]]
    for x in seq[1:]:
        if x!=out[-1]: out.append(x)
    return out
def f(g):
    # 1) reduce to one row of each equal run (dedupe consecutive equal rows), keep original order
    rows=[tuple(r) for r in g]
    rg=[]; prev=None
    for r in rows:
        if prev!=r: rg.append(list(r)); prev=r
    w=len(rg[0]); H=len(rg)
    cols=[[c[i] for i in range(H)] for c in [ [rg[i][j] for i in range(H)] for j in range(w) ]]
    cg=list(collapse(cols))
    return [[cg[j][i] for j in range(len(cg))] for i in range(H)]
